import modelsfrom sqlalchemy import text, inspectfrom database import engine, Basedef main():    # 1. Test MySQL connection    with engine.connect() as connection:        result = connection.execute(            text("SELECT DATABASE()")        )        print("Connected database:", result.scalar())    # 2. See registered tables    print("Registered Models:")    print(list(Base.metadata.tables.keys()))    # 3. Create tables    Base.metadata.create_all(bind=engine)    # 4. Check actual MySQL tables    inspector = inspect(engine)    print("Tables in MySQL:")    print(inspector.get_table_names())if __name__ == "__main__":    main()